#include <stdio.h>

int main(void) {
    int n;
    scanf("%d", &n);

    int stack[100000];
    int top = 0;

    for (int i = 0; i < n; i++) {
        int x;
        scanf("%d", &x);

        if (x == 0) {
            if (top > 0) top--;
        } else {
            stack[top++] = x;
        }
    }

    int sum = 0;
    for (int i = 0; i < top; i++) {
        sum += stack[i];
    }

    printf("%d\n", sum);
    return 0;
}
